import{_ as l,l as s,o as e,c as r,v as t,p as h,x as i,d as n,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"疏密偏差","description":"","frontmatter":{"title":"疏密偏差","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/iso-dense-bias.md","filePath":"litho/iso-dense-bias.md","lastUpdated":1789023840000}'),c={name:"litho/iso-dense-bias.md"};function E(A,a,m,D,_,u){const o=s("Mermaid");return e(),r("div",null,[a[1]||(a[1]=t('<h1 id="疏密偏差" tabindex="-1">疏密偏差 <a class="header-anchor" href="#疏密偏差" aria-label="Permalink to &quot;疏密偏差&quot;">​</a></h1><div class="epigraph"><p>同一条画线宽度，孤立环境与密栅环境印出的差，是邻近曲线上两个点，不是一条可以贴到全芯片的「经验纳米」。</p><footer>—— 据 Mack 对 iso–dense bias 与 through-pitch CD 的论述整理</footer></div><p><a href="/litho/ope-proximity">上一课</a>把光学邻近写成邻域对空中像的前向作用，并点名：一维上最常被叫到的切片是孤立对密集。缺口是把这条切片展开成可测的偏置，而不是再声明一次「邻居会改像」。线端缩短是二维的下一刀，留给<a href="/litho/line-end-shortening">下一课</a>。OPC 仍不出场。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>OPE 的身份证是整条 CD–pitch 曲线。产线口头却常只问一句：孤立线和密线差多少。疏密偏差（iso–dense bias）定义为同一画线宽度、同一剂量与焦点下</p> \\[\\Delta = \\mathrm{CD}_\\mathrm{iso}-\\mathrm{CD}_\\mathrm{dense}. \\]<p>符号随照明和 \\(k_1\\) 可正可负：偶极把某密节距的调制抬高，密线可能反而更胖或更瘦。缺口不是再画一遍邻域函数，而是：这两个点不能代替曲线，却是窗口重叠时最先撞上的一维约束——密线的 Bossung 与孤立线的 Bossung 往往对不齐。</p><p>把 \\(\\Delta\\) 写成胶批次或刻蚀微负载，会漏掉瞳面里级次重叠不同这一光学项。把 \\(\\Delta\\) 写成一个与 pitch 无关的常数，又会漏掉禁戒节距附近的尖峰。</p><h3 id="两个点不是整条-through-pitch" tabindex="-1">两个点不是整条 through-pitch <a class="header-anchor" href="#两个点不是整条-through-pitch" aria-label="Permalink to &quot;两个点不是整条 through-pitch&quot;">​</a></h3><p>密，通常指定 1:1 或设计规则允许的最密节距；孤立，指定光学直径之外没有邻居。中间那些「半密」节距才是曲线的身子，也常是禁戒所在。本课允许用 \\(\\Delta\\) 作切片名，禁止用它当 OPC 模型。</p><p><span class="marginnote">报疏密偏差必须声明：照明、NA、\\(\\sigma\\)、画线宽度、剂量、焦点、ADI 还是 AEI。换偶极取向，\\(\\Delta\\) 会改号。省略条件的「我们层偏置 8 nm」不能进后课修版。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>量测：固定剂量焦点，扫 pitch，得到 CD–pitch；再在同一场里放足够空的孤立线。\\(\\Delta\\) 是曲线两端（或指定两 pitch）的差。换环形、偶极、四极，曲线峰谷移动，偏置跟着移动——这证明主导项是空中像，不是当天显影液。</p><p>模拟：Hopkins / TCC 已经在光学课里；比较「只有目标线」与「左右加上等宽邻线」的阈值 CD，差就是光学 iso–dense。胶扩散与刻蚀负载会再叠一层工艺偏置。拆开的办法是同一掩模、同一胶、只改照明：光学项动，纯刻蚀项不动。</p><h3 id="窗口重叠" tabindex="-1">窗口重叠 <a class="header-anchor" href="#窗口重叠" aria-label="Permalink to &quot;窗口重叠&quot;">​</a></h3><p>密集与孤立要落在同一曝光–散焦窗里，才叫这一层可印。\\(\\Delta\\) 大，等于两条 Bossung 在 CD 轴上错开，重叠窗变瘦。减 \\(\\Delta\\) 的光学手段是换照明或加助条改孤立线的空中像；化学手段是后课的 PEB 与显影。本课只承认偏置会吃窗口，不把 RET 目录做完。</p>',16)),(e(),h(d,null,{default:i(()=>[p(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20PITCH%5B%22CD-pitch%20%E6%9B%B2%E7%BA%BF%22%5D%20--%3E%20DENSE%5B%22%E5%AF%86%E6%A0%85%20CD%22%5D%0A%20%20PITCH%20--%3E%20ISO%5B%22%E5%AD%A4%E7%AB%8B%20CD%22%5D%0A%20%20DENSE%20--%3E%20BIAS%5B%22%E7%96%8F%E5%AF%86%E5%81%8F%E5%B7%AE%20%CE%94%22%5D%0A%20%20ISO%20--%3E%20BIAS%0A%20%20BIAS%20--%3E%20WIN%5B%22%E9%87%8D%E5%8F%A0%E5%B7%A5%E8%89%BA%E7%AA%97%22%5D%0A%20%20BIAS%20--%3E%20LES%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E7%BA%BF%E7%AB%AF%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>密栅能量集中在有限衍射级，部分相干决定级间如何进瞳；孤立线频谱宽，像更接近点扩散与边沿响应。同一阈值切两条剖线，宽度不必相等。低 \\(k_1\\) 时通带更挤，两端差涨——与上一课 OPE「低 \\(k_1\\) 成为一阶」是同一条穷途的一维读数。</p><p>剂量改占空比：过曝通常让密线空间变宽、线变瘦，孤立线也瘦，但斜率不同，\\(\\Delta\\) 随剂量走。焦点改调制：密栅对离焦更敏感的那些 pitch，偏置会在焦轴上翻。所以 \\(\\Delta\\) 是窗上的函数，不是掩模上写死的一个偏置表项。</p><p><span class="marginnote">刻蚀微负载也制造疏密差，而且常与光学同号或反号。签核要 ADI 与 AEI 各报一次 \\(\\Delta\\)。只在胶上把偏置修到零，硬掩模上可以再裂开。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写助条放置、不写模型基 OPC、不把某节点的纳米偏置当普适常数。电子束写掩模的密度效应是后课 PEC，与晶圆侧 iso–dense 不是同一算子。</p><p>二维：线端、拐角、SRAM 对角邻居，用 \\(\\Delta\\) 盖不住。下一课只切线端缩短这一刀，仍然不是全芯片。MEEF 在密节距和孤立上各是一个数，偏置最大的 pitch 往往也是掩模误差最被放大的地方，两张图叠着看，仍不要合成「经验纳米」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>疏密偏差是 OPE 曲线上孤立与密集两个点的差，不是全芯片偏置。</li><li>\\(\\Delta\\) 随照明、剂量、焦点变；换瞳会改号。</li><li>密与孤立的 Bossung 错开，重叠窗变瘦。</li><li>光学项与胶/刻蚀项要拆；ADI、AEI 分报。</li><li>线端是下一课的二维切片。</li><li>出处：Mack, <em>Fundamental Principles of Optical Lithography</em>。</li></ul>',9))])}const P=l(c,[["render",E]]);export{C as __pageData,P as default};
